// Generated by Cypress Author on 2026-10-19
//
// REL 06 · REL 07 (P0) — Plano_de_Testes_QA_MatchWallet.md §8.
// O recorte por período de vínculo e a proteção real do arquivo são do servidor (ver
// e2e/real/isolamento.cy.ts). Aqui: a tela lista só o que a API devolve e trata a recusa do download.

const RELATORIOS = [
  {
    id: 'r-2026-10',
    mesReferencia: '2026-10',
    titulo: 'Relatório Outubro 2026',
    geradoEm: '2026-10-05T00:00:00.000Z',
    tamanhoBytes: 2048,
  },
  {
    id: 'r-2025-12',
    mesReferencia: '2025-12',
    titulo: 'Relatório Dezembro 2025',
    geradoEm: '2025-12-05T00:00:00.000Z',
    tamanhoBytes: 2048,
  },
]

describe('Plano QA · Relatórios do cliente', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('cliente')
  })

  it('REL 06 · API devolve só relatórios do período de vínculo → lista agrupada por ano sem itens extras', () => {
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: RELATORIOS, total: 2, page: 1, pageSize: 100 },
      'lista',
    )
    cy.visit('/relatorios')
    cy.wait('@lista')

    cy.contains('h2', '2026').should('be.visible')
    cy.contains('h2', '2025').should('be.visible')
    cy.contains('button', 'Baixar').should('exist')
    cy.get('[aria-label^="Baixar "]').should('have.length', RELATORIOS.length)
    cy.contains('Relatório Outubro 2026').should('be.visible')
    cy.contains('Relatório Dezembro 2025').should('be.visible')
  })

  it('REL 06 · cliente sem relatório no vínculo → mostra o estado vazio, não um erro de acesso', () => {
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [], total: 0, page: 1, pageSize: 100 },
      'lista',
    )
    cy.visit('/relatorios')
    cy.wait('@lista')

    cy.contains('Nenhum relatório disponível ainda.').should('be.visible')
    cy.get('[role="alert"]').should('not.exist')
  })

  it('REL 07 · download recusado pela API (403) → não gera arquivo e o botão volta a ficar disponível', () => {
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [RELATORIOS[0]], total: 1, page: 1, pageSize: 100 },
      'lista',
    )
    cy.stubErroApi(
      'GET',
      '/relatorios/*/download',
      { status: 403, code: 'FORBIDDEN', message: 'Sem permissão para este relatório.' },
      'download',
    )
    cy.visit('/relatorios')
    cy.wait('@lista')

    cy.get('[aria-label="Baixar Relatório Outubro 2026"]').click()

    cy.wait('@download').its('response.statusCode').should('eq', 403)
    cy.get('[aria-label="Baixar Relatório Outubro 2026"]').should('be.enabled')
    cy.contains('Baixando…').should('not.exist')
  })
})

export {}
